                                .add(invoiceDataFaker.company().name())
                                .add(invoiceDataFaker.date().past(1).get())
                                .add(invoiceDataFaker.number().twoDigitDecimalValue())
                )
        ));
    }

    @Step("When I make a POST request to \"\{\"path\}\"\" with the invoice data")
    public void createInvoice(String path, Table invoiceData) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(org.springframework.http.MediaType.APPLICATION_JSON);
