            gaugeExecutionContext.put("responseStatus", ex.getStatusCode().value());
            gaugeExecutionContext.put("responseBody", ex.getResponseBodyAsString());
            throw new GaugeException("Failed creating invoice. " + ex.getMessage());
        }
