      import io.github.gmk120y.gauge.stepdefinition.WhenStep;
      import org.assertj.core.api.Assertions;
      import org.junit.jupiter.api.AssertionsThrown;
      import org.springframework.beans.factory.annotation.Autowired;
      import org.springframework.boot.test.context.SpringBootTest;
      import org.springframework.boot.test.web.client.TestRestTemplate;
      import org.springframework.http.HttpEntity;
      import org.springframework.http.HttpHeaders;
      import org.springframework.http.HttpStatus;
      import org.springframework.http.ResponseEntity;

      import java.util.ArrayList;
      import java.util.LinkedHashMap;
      import java.util.List;
      import java.util.Map;

      @SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
      public class InvoiceManagementStepDefinitions {

        @Autowired
        private TestRestTemplate template;

        private String baseUrl;

        @Given("a running Invoice Management service with Oracle EBS connectivity")
        public void givenRunningInvoiceManagementService() {
          this.baseUrl = String
              .format("http://localhost:%d/invoices", template.getPort());
        }

        @When("I send a POST request to '{endpoint}'")
        public void whenISendPostRequestToEndpoint(String endpoint) {
          String url = baseUrl + endpoint;
          HttpHeaders headers = new HttpHeaders();
          headers.add("Content-Type", "application/json");

          Map<String, Object> invoiceDetails = new LinkedHashMap<>();
          invoiceDetails.put("invoiceNumber", "${invNo}");
          invoiceDetails.put("customerName", "${customerName}");
          List<Map<String, Object>> items = new ArrayList<>();
          items.add(Map.of("itemCount", "${itemCount}", "itemPrice", "${itemPrice}"));
          items.add(Map.of("itemCount", "${itemCount}", "itemPrice", "${itemPrice}"));
          invoiceDetails.put("items", items);

          HttpEntity<Map<String, Object>> request = new HttpEntity<>(invoiceDetails, headers);

          ResponseEntity<String> responseEntity = template.postForEntity(url, request, String.class);

          Assertions.assertThat(responseEntity.getStatusCode()).isEqualTo(HttpStatus.OK);
        }

        @Then("the HTTP status code should be {int}")
        public void thenHttpStatusCodeShouldBe(int statusCode) {
          Assertions.assertThat(lastResponseEntity.getStatusCodeValue()).isEqualTo(statusCode);
        }

        @Then("the response contains the invoice details")
        public void thenResponseContainsInvoiceDetails() {
          Map<String, Object> responseObject = parseJsonToMap(lastResponseEntity.getBody());

          Assertions.assertThat((String) responseObject.get("invoiceNumber")).containsSubstring("${invNo}");
          Assertions.assertThat((String) responseObject.get("customerName")).containsSubstring("${customerName}");
          Assertions.assertThat(((List<Map<String, Object>>) responseObject.get("items")).get(0)).containsEntry("itemCount", "${itemCount}");
          Assertions.assertThat(((List<Map<String, Object>>) responseObject.get("items")).get(0)).containsEntry("itemPrice", "${itemPrice}");
          Assertions.assertThat(((List<Map<String, Object>>) responseObject.get("items")).get(1)).containsEntry("itemCount", "${itemCount}");
          Assertions.assertThat(((List<Map<String, Object>>) responseObject.get("items")).get(1)).containsEntry("itemPrice", "${itemPrice}");
        }

        @SuppressWarnings("unchecked")
        private static Map<String, Object> parseJsonToMap(String json) {
          return com.fasterxml.jackson.databind.ObjectMapper
              .mapper()
              .readValue(json, LinkedHashMap.class);
        }

        private ResponseEntity<String> lastResponseEntity;

        @WhenStep
        @When("the request body is:")
        public void whenRequestBodyIs(String requestBody) {
          lastResponseEntity = template.postForEntity(baseUrl, requestBody, String.class);
        }

        @ThenStep
        @Then("the response contains:")
        public void thenResponseContains(String responseBody) {
          Map<String, Object> expectedResponse = parseJsonToMap(responseBody);

          Map<String, Object> responseObject = parseJsonToMap(lastResponseEntity.getBody());

          AssertionsThrown.from(Assertions.assertThat(responseObject)).isEqualToComparingOnlyGivenFields(expectedResponse);
        }
      }
      ```

