    "Lilac": [],
    "Daisy": [],
    "Marigold": [],
    "Chrysanthemum": []
}

flowers = ["Lilac", "Daisy", "Marigold", "Chrysanthemum"]

for flower in flowers:
    category_key = ""
    if "Li" in flower[:2]:
        category_key = "Lilac"
    elif "Da" in flower[:2]:
        category_key = "Daisy"
    elif "Ma" in flower[:2]:
        category_key = "Marigold"
    elif "Ch" in flower[:2]:
        category_key = "Chrysanthemum"

    categories[category_key] = categories.get(category_key, []) + [flower]

print(categories)
```

