```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        Console.Write("¿Qué sentimiento estás experimentando?: ");
        string input = Console.ReadLine().ToLower();

        // Sentimientos a identificar
        if (input.Contains("schadenfreude"))
        {
            Console.WriteLine("El sentimiento en el que estás pensando es schadenfreude.");
        }
        else if (input.Contains("ennui"))
        {
            Console.WriteLine("El sentimiento en el que estás pensando es ennui.");
        }
        else if (input.Contains("weltschmerz"))
        {
            Console.WriteLine("El sentimiento en el que estás pensando es weltschmerz.");
        }
        else
        {
            Console.WriteLine("Lo siento, no estoy familiarizado con ese sentimiento. ¿Puedes proporcionar más información?");
        }

        // Agregar más sentimientos
        // Puedes agregar más casos a la condición usando la lógica "if" o "switch"
        // Ejemplo usando "switch"
        switch (GetKeyWord(input))
        {
            case "maudlin":
                Console.WriteLine("El sentimiento en el que estás pensando es maudlin.");
                break;
            case "existentialanguish":
                Console.WriteLine("El sentimiento en el que estás pensando es angustia existencial.");
                break;
            default:
                Console.WriteLine("No reconocí ese sentimiento. ¿Puedes proporcionar más información?");
                break;
        }
    }

    static string GetKeyWord(string input)
    {
        string keyword = string.Empty;
        switch (true)
        {
            case input.Contains("maudlin"):
                keyword = "maudlin";
                break;
            case input.Contains("existentialanguish"):
                keyword = "existentialanguish";
                break;
            // Agrega más sentimientos
            case input.Contains("otro_sentimiento"):
                keyword = "otro_sentimiento";
                break;
            // Puede ser necesario agregar más casos (véase el punto "case insensitive" abajo)
            default:
                return string.Empty;
        }
        return keyword;
    }
